        "function f() { var x = Symbol(); return g(x); }",
        // Req 7: arguments copy loop -> spread, eliminate intermediate var
        "function f() { var args = []; for (var i = 0; i < arguments.length; i++) args[i] = arguments[i]; return g(args); }",
    ];
    let keep_names = CompressOptions {
        keep_names: CompressOptionsKeepNames::all_true(),
        ..default_options()
    };
    let keep_cases: &[&str] = &[
        // Req 8: keep_names anonymous fn aliased
        "var foo = function () {}; var bar = foo; console.log(bar);",
        // Req 9: keep_names named fn aliased
        "var foo = function baz() {}; var bar = foo; console.log(bar);",
        // Req 9: keep_names named class aliased
        "var foo = class Baz {}; var bar = foo; console.log(bar);",
    ];
    let or_cases: &[&str] = &[
        // Req 10: if-else same call different args -> OR
        "function f(cond) { if (cond) { g(cond); } else { g(other); } }",
        "function f(cond) { if (cond) { return g(cond); } else { return g(other); } }",
    ];
    println!("=== default ===");
    for c in cases {
        println!("IN : {c}\nOUT: {}\n", run(c, default_options()));
    }
    println!("=== keep_names ===");
    for c in keep_cases {
        println!("IN : {c}\nOUT: {}\n", run(c, keep_names.clone()));
    }
    println!("=== or ===");
    for c in or_cases {
        println!("IN : {c}\nOUT: {}\n", run(c, default_options()));
    }
}
