+/// Whether accessing the global with the given name is known to be side-effect-free.
+///
+/// This covers well-known built-in globals (which are always safe) and a small set of
+/// recognized known-safe environment globals (`console`, `document`, `window`, `fetch`).
+fn is_known_safe_global(name: &str) -> bool {
+    matches!(
+        name,
+        // well-known built-in globals
+        "Math"
+            | "Array"
+            | "Object"
+            | "JSON"
+            | "Reflect"
+            | "Symbol"
+            | "Promise"
+            | "Map"
+            | "Set"
+            | "WeakMap"
+            | "WeakSet"
+            | "parseInt"
+            | "parseFloat"
+            | "isNaN"
+            | "isFinite"
+            | "encodeURI"
+            | "decodeURI"
+            | "globalThis"
+            // recognized known-safe environment globals
+            | "console"
+            | "document"
+            | "window"
+            | "fetch"
+    )
+}
+
+/// Whether reading `property` on the built-in global `object` is side-effect-free.
+///
+/// Only a small allow-list of known properties per built-in is considered safe;
+/// any other property is treated as potentially side-effectful.
+fn is_known_global_property(object: &str, property: &str) -> bool {
+    match object {
+        "Math" => matches!(property, "PI" | "E" | "abs" | "floor" | "random"),
+        "Object" => matches!(property, "keys" | "create" | "assign" | "prototype"),
+        "Reflect" => matches!(property, "apply" | "get"),
+        "Symbol" => matches!(property, "iterator" | "asyncIterator"),
+        "JSON" => matches!(property, "parse" | "stringify"),
+        "console" => matches!(property, "log" | "error" | "warn"),
+        _ => false,
+    }
+}
+
+/// Whether `property` is a known method on `Object.prototype` that is safe to read
+/// through the three-level chain `Object.prototype.<property>`.
+fn is_object_prototype_property(property: &str) -> bool {
+    matches!(
+        property,
+        "hasOwnProperty" | "isPrototypeOf" | "toString" | "valueOf" | "propertyIsEnumerable"
+    )
+}
