+impl<'a> MayHaveSideEffects<'a> for ArrayExpression<'a> {
+    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
+        self.elements.iter().any(|element| element.may_have_side_effects(ctx))
+    }
+}
